const items=$input.all();
if(items.length!==1) throw new Error('Requires one telemetry item per execution');
const d=items[0].json;
const room=d.room??d.room_id;
const now=new Date();
const isManual=$('Manual Trigger').isExecuted;
const time=d.timestamp==null?now.getTime():Date.parse(d.timestamp);
let error='';
if(typeof room!=='string'||!room.trim()||typeof d.device_id!=='string'||!d.device_id.trim()) error='Thiếu room hoặc device_id';
else if(typeof d.occupancy!=='boolean') error='occupancy phải là boolean true/false';
else if(!Number.isFinite(time)||time>now.getTime()+30000||now.getTime()-time>120000) error='Timestamp không hợp lệ, quá cũ hoặc trong tương lai';
else if(!Number.isFinite(d.temperature)||d.temperature< -40||d.temperature>80||!Number.isFinite(d.light_percent)||d.light_percent<0||d.light_percent>100) error='WF08 cần temperature dạng số và light_percent từ 0 đến 100';
return [{json:{...d,room:typeof room==='string'?room.trim():room,valid:!error,error,
 evaluated_at:now.toISOString(),backend_base_url:'http://host.docker.internal:3001/api',
 test_mode:isManual,
 test_empty_seconds:isManual&&Number.isFinite(d.test_empty_seconds)?Math.max(0,Math.min(3600,d.test_empty_seconds)):0,
 test_hour:isManual&&Number.isInteger(d.test_hour)&&d.test_hour>=0&&d.test_hour<=23?d.test_hour:null}}];

const d=$('Telemetry dau vao').first().json;
const c=$('Doc Config').first().json;
const old=$input.first().json;
const has=old.room_id===d.room;
const now=new Date(d.evaluated_at);
let emptySince=null,mode='OCCUPIED';
let fan=has?old.fan_target:'KEEP';
let light=has?old.light_target:'KEEP';
if(d.occupancy){
 if(d.temperature>=c.fan_on_temperature) fan='ON';
 else if(d.temperature<=c.fan_off_temperature) fan='OFF';
 if(d.light_percent<=c.light_on_below_percent) light='ON';
 else if(d.light_percent>=c.light_off_above_percent) light='OFF';
}else{
 emptySince=has && old.occupancy===false && old.empty_since ? old.empty_since : now.toISOString();
 // Manual demo only: simulate continuous empty time without waiting two minutes.
 if(d.test_mode && d.test_empty_seconds>0)
  emptySince=new Date(now.getTime()-d.test_empty_seconds*1000).toISOString();
 const seconds=Math.max(0,(now.getTime()-Date.parse(emptySince))/1000);
 if(seconds>=c.empty_delay_seconds){mode='EMPTY';fan='OFF';light='OFF';}
 else mode='WAITING';
}
const requests=[];
if(mode!=='WAITING'){
 for(const [command_type,target,previous] of [['FAN',fan,old.fan_target],['LIGHT',light,old.light_target]]){
  const enteringEmpty=mode==='EMPTY' && (!has||old.mode!=='EMPTY');
  const reoccupied=d.occupancy && (!has||old.occupancy===false);
  if(target!=='KEEP' && (!has||target!==previous||enteringEmpty||reoccupied))
   requests.push({device_id:d.device_id,command_type,action:target,source:'AUTO',
    payload:{source_workflow:'WF08_ENERGY',room:d.room,reason:mode==='EMPTY'?'ROOM_EMPTY':'OCCUPIED_COMFORT'}});
 }
}
const elapsed=emptySince?Math.max(0,(now.getTime()-Date.parse(emptySince))/1000):0;
return [{json:{
 state_to_save:{occupancy:d.occupancy,empty_since:emptySince,fan_target:fan,light_target:light,mode,observed_at:d.evaluated_at},
 result:{room:d.room,room_id:d.room,device_id:d.device_id,source:'WF08_ENERGY',timestamp:d.evaluated_at,
  wf08_status:requests.length?'ACTION':mode==='WAITING'?'WAITING':'NO_CHANGE',mode,
  should_dispatch:requests.length>0,command_requests:requests,
  fan_target:fan,light_target:light,empty_seconds:Math.floor(elapsed),
  remaining_seconds:mode==='WAITING'?Math.max(0,Math.ceil(c.empty_delay_seconds-elapsed)):0,
  test_mode:d.test_mode,
  message:mode==='EMPTY'?'Phòng trống đủ thời gian: đề nghị tắt quạt và đèn':
   mode==='WAITING'?'Đang chờ xác nhận phòng trống đủ thời gian':'Điều chỉnh theo nhiệt độ và ánh sáng khi có người'}
}}];
